'use strict';
window.FinanceView=(()=>{
 let selectedBank='abanca';
 let db,home,user,show,rows=[],accounts=[],sources=[],links=[],page=0,selected=null,investmentOnly=false,loading=false;
 const $=id=>document.getElementById(id),money=v=>new Intl.NumberFormat('pt-PT',{style:'currency',currency:'EUR'}).format(v),fmt=d=>new Intl.DateTimeFormat('pt-PT',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
 const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Lisbon'}).format(new Date());
 const cents=r=>Math.round(Number(r.amount)*100),sum=rs=>rs.reduce((n,r)=>n+cents(r),0)/100;
 const names={expense:'Spending',income:'Income',refund:'Refund',investment:'Savings / investing',transfer:'Transfer',withdrawal:'Cash withdrawal',review:'Needs review',opening_balance:'Opening balance'};
 function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
 function error(text){$('finance-message').textContent=text;$('finance-message').className='message error';}
 function account(id){return accounts.find(a=>a.id===id)?.label||'Account';}
 async function all(table){let result=[];for(let offset=0;offset<10000;offset+=750){const r=await db.from(table).select('*').eq('household_id',home).order(table==='finance_transaction_sources'?'transaction_id':'id').range(offset,offset+749);if(r.error)throw r.error;result.push(...r.data);if(r.data.length<750)return result;}throw Error('More than 10,000 transactions need server pagination. No partial totals have been shown.');}
 function matchesAccount(r){return AccountReports.matches(r,accounts,selectedBank,$('finance-account').value);}
 function scopeLabel(){const selected=$('finance-account').value;return selected==='all'?AccountReports.bankName(selectedBank)+' · todas as contas':account(selected);}
 function accountOptions(previous='all'){$('finance-account').replaceChildren();const all=el('option','Todas as contas · '+(selectedBank==='all'?'família':AccountReports.bankName(selectedBank)));all.value='all';$('finance-account').append(all);const included=accounts.filter(a=>selectedBank==='all'||AccountReports.bankFor(a)===selectedBank);for(const acc of included){const o=el('option',acc.label);o.value=acc.id;$('finance-account').append(o);}if(included.some(a=>a.id===previous))$('finance-account').value=previous;}
 function renderReports(){const label=scopeLabel();$('account-scope').textContent=label;$('report-scope').textContent='Monthly report for '+label+'.';document.querySelectorAll('[data-bank]').forEach(b=>{b.classList.toggle('active',b.dataset.bank===selectedBank);b.setAttribute('aria-pressed',b.dataset.bank===selectedBank?'true':'false');});$('account-report-rows').replaceChildren();const ms=AccountReports.report(rows,accounts,selectedBank,$('finance-account').value,today());for(const m of ms){const tr=el('tr');tr.append(el('td',m.month),el('td',String(m.count)));for(const k of ['received','paid','spending','investing','transferOut'])tr.append(el('td',money(m[k]/100),'number'));$('account-report-rows').append(tr);}if(!ms.length){const tr=el('tr'),td=el('td','No supplied movements for this account.');td.colSpan=7;tr.append(td);$('account-report-rows').append(tr);}}
 function downloadReport(){const rs=AccountReports.report(rows,accounts,selectedBank,$('finance-account').value,today());const safe=v=>'"'+String(v).replace(/"/g,'""')+'"';const lines=[['Bank/account','Month','Movements','Received EUR','Paid out EUR','Spending less refunds EUR','Savings/investing EUR','Transfers out EUR']];for(const r of rs)lines.push([scopeLabel(),r.month,r.count,...['received','paid','spending','investing','transferOut'].map(k=>(r[k]/100).toFixed(2))]);const blob=new Blob(['\uFEFF'+lines.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=el('a');a.href=URL.createObjectURL(blob);a.download='nesti-'+selectedBank+'-monthly-report.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
 function filtered(){const month=$('finance-month').value,acc=$('finance-account').value;return rows.filter(r=>r.booked_on<=today()&&(month==='all'||r.booked_on.startsWith(month))&&matchesAccount(r));}
 function bars(id,groups){const target=$(id);target.replaceChildren();const entries=Object.entries(groups).sort(id==='monthly-bars'?((a,b)=>a[0].localeCompare(b[0])):((a,b)=>b[1]-a[1]));if(!entries.length){target.append(el('p','No matching recorded movements.','muted'));return;}const max=Math.max(...entries.map(x=>Math.abs(x[1])),1);for(const [label,value] of entries){const row=el('div',undefined,'bar-row');const title=el('div',undefined,'bar-title');title.append(el('span',label),el('strong',money(value)));const track=el('div',undefined,'bar-track'),bar=el('div',undefined,'bar-fill');bar.style.width=Math.max(0,Math.abs(value)/max*100)+'%';track.append(bar);row.append(title,track);target.append(row);}}
 function planningContext(){return {db,home,user,rows,accounts,sources,links,show,bank:selectedBank,accountId:$('finance-account').value,month:$('finance-month').value,scopeLabel:scopeLabel(),setMonth:m=>{if(![...$('finance-month').options].some(o=>o.value===m)){const o=el('option',m);o.value=m;$('finance-month').prepend(o);}$('finance-month').value=m;render();}};}
 function render(){
  renderReports();const rs=filtered(),month=$('finance-month').value;const spending=rs.filter(r=>['expense','refund'].includes(r.flow_kind));$('money-in').textContent=money(sum(rs.filter(r=>cents(r)>0)));$('money-out').textContent=money(-sum(rs.filter(r=>cents(r)<0)));$('money-spending').textContent=money(-sum(spending));$('finance-review-count').textContent=rs.filter(r=>r.review_status==='needs_review').length;
  $('coverage-alert').textContent=((month==='2026-08'||month==='all')&&selectedBank!=='activo'?'Late August is missing from the ABANCA exports. ':'')+(month===today().slice(0,7)?'This month is still in progress. ':'')+'Figures are based on supplied statements and current classifications; they are not a live bank balance.';
  const groups={};for(const r of spending)groups[r.category||'Uncategorized']=(groups[r.category||'Uncategorized']||0)-cents(r)/100;bars('spending-bars',groups);
  const monthly={};for(const r of rows.filter(r=>r.booked_on<=today()&&['expense','refund'].includes(r.flow_kind)&&matchesAccount(r))){const m=r.booked_on.slice(0,7);monthly[m]=(monthly[m]||0)-cents(r)/100;}bars('monthly-bars',monthly);
  const inv={};for(const r of rs.filter(r=>r.flow_kind==='investment')){const label=/SGF/i.test(r.description)?'SGF contributions':/DEGIRO/i.test(r.description)?'DEGIRO movements':'Other savings / investment movements';inv[label]=(inv[label]||0)-cents(r)/100;}bars('investment-bars',inv);
  const scoped=rows.filter(matchesAccount);const future=scoped.filter(r=>r.booked_on>today()).length;$('finance-date-note').textContent=scoped.length+' imported movements. '+future+' future-booked movements are excluded until their booking date.';renderRows();window.FinancePlanning?.update(planningContext());
 }
 function renderRows(){
  const q=$('transaction-search').value.toLocaleLowerCase();let rs=filtered().filter(r=>(!$('transaction-review-only').checked||r.review_status==='needs_review')&&(!$('transaction-macro').value||FamilyAnalytics.taxonomy(r).type===$('transaction-macro').value)&&(!investmentOnly||r.flow_kind==='investment')&&(!q||(r.description+' '+(r.category||'')+' '+FamilyAnalytics.taxonomy(r).detail+' '+account(r.account_id)).toLocaleLowerCase().includes(q))).sort((a,b)=>b.booked_on.localeCompare(a.booked_on)||a.id.localeCompare(b.id));
  const pages=Math.max(1,Math.ceil(rs.length/40));page=Math.min(page,pages-1);$('transaction-count').textContent=rs.length+' matching transactions'+(investmentOnly?' · savings / investment movements':'')+'. Future-booked entries are excluded.';$('transaction-rows').replaceChildren();for(const r of rs.slice(page*40,page*40+40)){const tr=el('tr');tr.append(el('td',fmt(r.booked_on)));const desc=el('td');desc.append(el('span',r.description),el('small',account(r.account_id),'muted'));const tax=FamilyAnalytics.taxonomy(r),categoryCell=el('td',r.category||'Por classificar');categoryCell.append(el('small',tax.detail+' · '+({fixed:'Fixa',variable:'Variável',unclassified:'Por classificar'}[tax.type])+(tax.suggested?' · sugestão':''),'muted'));tr.append(desc,categoryCell,el('td',names[r.flow_kind]),el('td',money(Number(r.amount)),'number'));const action=el('td'),b=el('button',r.review_status==='reviewed'?'Reviewed':'Review','text-button');b.type='button';b.onclick=()=>edit(r);action.append(b);tr.append(action);$('transaction-rows').append(tr);}
  if(!rs.length){const tr=el('tr'),td=el('td','No matching transactions.');td.colSpan=6;tr.append(td);$('transaction-rows').append(tr);}$('transactions-prev').disabled=page===0;$('transactions-next').disabled=page>=pages-1;$('transactions-page-label').textContent='Page '+(page+1)+' of '+pages;
 }
 async function edit(r){selected={...r};$('classification-description').textContent=fmt(r.booked_on)+' · '+account(r.account_id)+' · '+money(Number(r.amount))+'\n'+r.description;$('classification-category').value=r.category||'';$('classification-flow').value=r.flow_kind;const tax=FamilyAnalytics.taxonomy(r),canEdit=Object.prototype.hasOwnProperty.call(r,'subcategory');$('classification-subcategory').value=tax.detail==='A rever'?'':tax.detail;$('classification-expense-type').value=tax.type;$('classification-necessity').value=tax.need;for(const id of ['classification-subcategory','classification-expense-type','classification-necessity'])$(id).disabled=!canEdit;$('taxonomy-pending').hidden=canEdit;$('classification-message').textContent='';$('classification-sources').replaceChildren();$('classification-dialog').showModal();try{const links=await db.from('finance_transaction_sources').select('source_id,source_row').eq('household_id',home).eq('transaction_id',r.id);if(links.error)throw links.error;for(const l of links.data){const source=sources.find(s=>s.id===l.source_id);if(source){const a=el('a',source.file_name+' · source row '+l.source_row,'text-link');a.href=source.source_url;a.target='_blank';a.rel='noopener';$('classification-sources').append(a);}}}catch(e){$('classification-message').textContent='Source link could not load: '+e.message;}}
 async function save(e){e.preventDefault();if(!selected||$('classification-save').disabled)return;$('classification-save').disabled=true;try{const category=$('classification-category').value.trim()||null,flow_kind=$('classification-flow').value;if(['expense','income'].includes(flow_kind)&&!category)throw Error('Add a category for spending or income.');const patch={category,flow_kind,review_status:flow_kind==='review'?'needs_review':'reviewed'};if(Object.prototype.hasOwnProperty.call(selected,'subcategory'))Object.assign(patch,{subcategory:$('classification-subcategory').value.trim()||null,expense_type:$('classification-expense-type').value,necessity:$('classification-necessity').value});const r=await db.from('finance_transactions').update(patch).eq('household_id',home).eq('id',selected.id).eq('version',selected.version).select('*');if(r.error)throw r.error;if(!r.data.length)throw Error('This transaction changed since you opened it. Close, refresh, and review the latest version. Your changes have not overwritten it.');const idx=rows.findIndex(t=>t.id===selected.id);rows[idx]=r.data[0];$('classification-dialog').close();render();}catch(e){$('classification-message').textContent=e.message;}finally{$('classification-save').disabled=false;}}
 function renderSources(){$('abanca-gap-panel').hidden=selectedBank==='activo';$('source-cards').replaceChildren();for(const s of sources.filter(matchesAccount)){const card=el('article',undefined,'panel');card.append(el('p',account(s.account_id),'eyebrow'),el('h2',s.file_name),el('p',fmt(s.first_on)+' – '+fmt(s.last_on)+' · booking dates'),el('p',s.row_count+' movements · '+s.balance_checks+' running-balance checks passed.'),el('p',s.warning,'small muted'));const a=el('a','Open original statement ↗','text-link');a.href=s.source_url;a.target='_blank';a.rel='noopener';card.append(a);$('source-cards').append(card);}}
 async function refresh(){if(loading)return;loading=true;$('refresh-finances').disabled=true;error('');try{const previousMonth=$('finance-month').value,previousAccount=$('finance-account').value;[rows,accounts,sources,links]=await Promise.all([all('finance_transactions'),all('finance_accounts'),all('finance_sources'),all('finance_transaction_sources')]);const months=[...new Set(rows.filter(r=>r.booked_on<=today()).map(r=>r.booked_on.slice(0,7)))].sort().reverse();$('finance-month').replaceChildren();for(const m of months){const o=el('option',new Intl.DateTimeFormat('pt-PT',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(m+'-15T12:00:00Z')));o.value=m;$('finance-month').append(o);}const allOpt=el('option','Todos os meses disponíveis');allOpt.value='all';$('finance-month').append(allOpt);if(months.includes(previousMonth)||previousMonth==='all')$('finance-month').value=previousMonth;accountOptions(previousAccount);$('category-options').replaceChildren(...[...new Set(rows.map(r=>r.category).filter(Boolean))].sort().map(c=>{const o=el('option');o.value=c;return o;}));renderSources();render();await window.FinancePlanning?.sync(planningContext());}catch(e){rows=[];for(const id of ['money-in','money-out','money-spending','finance-review-count'])$(id).textContent='Unavailable';for(const id of ['transaction-rows','spending-bars','monthly-bars','investment-bars','account-report-rows'])$(id).replaceChildren();error('Financial figures could not load. '+e.message);}finally{loading=false;$('refresh-finances').disabled=false;}}
 let proposalRows=[];
 function wireSuggestions(){
  $('close-suggestions').onclick=()=>$('suggestions-dialog').close();
  $('suggest-classifications').onclick=()=>{proposalRows=filtered().flatMap(r=>{const s=ClassificationEngine.suggest(r,rows);return s?[{row:r,...s}]:[];}).slice(0,100);$('classification-suggestions').replaceChildren();$('suggestions-message').textContent=proposalRows.length?proposalRows.length+' propostas para rever.':'Sem novas sugestões seguras neste âmbito. Os movimentos ambíguos continuam disponíveis na revisão individual.';for(const [i,p] of proposalRows.entries()){const label=el('label',undefined,'suggestion-row'),check=el('input');check.type='checkbox';check.checked=true;check.dataset.proposal=String(i);const body=el('span');body.append(el('strong',p.row.description+' · '+money(Number(p.row.amount))),el('small',(p.row.category||'Sem categoria')+' → '+p.patch.category+' / '+(p.patch.subcategory||'Sem detalhe')),el('small',names[p.row.flow_kind]+' → '+names[p.patch.flow_kind]+' · '+p.reason));label.append(check,body);$('classification-suggestions').append(label);}$('apply-suggestions').disabled=!proposalRows.length;$('suggestions-dialog').showModal();};
  $('apply-suggestions').onclick=async()=>{const chosen=[...document.querySelectorAll('[data-proposal]:checked')].map(n=>proposalRows[Number(n.dataset.proposal)]);$('apply-suggestions').disabled=true;let saved=0,conflicts=0;try{for(const p of chosen){const r=await db.from('finance_transactions').update({...p.patch,review_status:'reviewed'}).eq('household_id',home).eq('id',p.row.id).eq('version',p.row.version).select('id');if(r.error)throw r.error;if(r.data.length)saved++;else conflicts++;$('suggestions-message').textContent=saved+' guardadas; '+conflicts+' conflitos preservados.';}await refresh();$('suggestions-message').textContent=saved+' classificações guardadas. '+conflicts+' registos alterados entretanto foram preservados. Fecha e volta a gerar sugestões para rever a versão mais recente.';}catch(e){$('suggestions-message').textContent=saved+' guardadas. '+e.message;}finally{$('apply-suggestions').disabled=true;}};
 }
 let wired=false;
 return {reset(){window.FinancePlanning?.reset();home=null;rows=[];accounts=[];sources=[];for(const id of ['transaction-rows','spending-bars','monthly-bars','investment-bars','source-cards','account-report-rows'])$(id)?.replaceChildren();},async start(client,currentUser,household,navigate){db=client;user=currentUser;show=navigate;if(home===household&&rows.length)return;home=household;if(!wired){wired=true;$('finance-month').onchange=$('finance-account').onchange=()=>{page=0;render();renderSources();};document.querySelectorAll('[data-bank]').forEach(b=>b.onclick=()=>{selectedBank=b.dataset.bank;accountOptions();page=0;render();renderSources();});$('download-account-report').onclick=downloadReport;$('refresh-finances').onclick=refresh;$('transaction-search').oninput=$('transaction-review-only').onchange=$('transaction-macro').onchange=()=>{page=0;renderRows();};$('transactions-prev').onclick=()=>{page--;renderRows();};$('transactions-next').onclick=()=>{page++;renderRows();};$('review-transactions').onclick=()=>{investmentOnly=false;$('transaction-review-only').checked=true;page=0;renderRows();show('transactions');};$('show-investment-transactions').onclick=()=>{investmentOnly=true;$('transaction-review-only').checked=false;page=0;renderRows();show('transactions');};document.querySelector('[data-page="transactions"]').addEventListener('click',()=>{investmentOnly=false;renderRows();});document.querySelector('[data-page="investments"]').addEventListener('click',()=>{selectedBank='all';accountOptions();render();renderSources();});document.querySelector('[data-page="evolution"]').addEventListener('click',()=>{selectedBank='all';accountOptions();render();renderSources();});$('classification-form').onsubmit=save;$('close-classification').onclick=()=>$('classification-dialog').close();wireSuggestions();}await refresh();show('analysis');}};
})();
